const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
let current=null, timer=null, visualPreviewTimer=null, visualPreviewVersion=0, activeTab='edits', page=location.pathname==='/settings'?'settings':'gallery', dirty=false, youtubeConnected=false, aiConfigured=false, aiProvider='opencode', aiOptions={}, projectCache=[], galleryQuery='', galleryStatus='all', galleryPage=1, galleryPageSize=12;
const transcriptionModels={tiny:'Rápida · menor qualidade',base:'Leve · rápida',small:'Equilibrada',medium:'Alta · recomendada','large-v3':'Máxima · mais lenta'};
