const studioThemes={graphite:'#151719',chalk:'#e7e3da',workshop:'#e5dccb'};
const previewPrefs=(()=>{try{const size=localStorage.getItem('recording-preview-size');return{size:['compact','balanced','wide'].includes(size)?size:'compact',collapsed:localStorage.getItem('recording-preview-collapsed')==='true'}}catch{return{size:'compact',collapsed:false}}})();
function applyTheme(theme,persist=true){if(!Object.hasOwn(studioThemes,theme))theme='graphite';document.documentElement.dataset.theme=theme;const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=studioThemes[theme];$$('[data-theme-choice]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.themeChoice===theme)));if(persist)try{localStorage.setItem('recording-theme',theme)}catch{}}
document.addEventListener('click',event=>{const choice=event.target.closest('[data-theme-choice]');if(choice)applyTheme(choice.dataset.themeChoice)});
